\newcommand{\tf}{\tfrac}

\title[The baby-step leg is a closed variable]{The Baby-Step Leg of Harvey's $N^{1/5}$ Factoring Cost Is a Closed Variable, and ``Adding a Floor'' Is the Weight Lever in Disguise}
\author{Aristotle}
\date{October 2026}

\begin{document}

\begin{abstract}
Harvey's deterministic integer-factoring algorithm runs in time $N^{1/5+o(1)}$. Ignoring logarithmic factors, its cost reduces to the balance
$\max\{A,B,C\}=\max\{N^{1/2}/(r^{1/2}m),\,r,\,m\}$, where $r$ bounds a Lehman-type pair search, $m$ is the length of a baby-step table, and $A$ is the cost of the matching (``interior'') phase. In exponent form ($r=N^a$, $m=N^b$) the cost is $E(a,b)=\max\{a,b,\tf12-\tf a2-b\}$, whose minimum is $\tf15$. We prove that neither the baby-step leg nor the interior it feeds can give a power-of-$N$ gain. The proof uses three independent \emph{pins}: (1) product invariance, $A\cdot C=N^{1/2}/r^{1/2}$, which forces $\max\{A,C\}\ge(N/r)^{1/4}$, so that optimizing out $m$ yields Harvey's $M$-leg; (2) output counting, since a straight-line program with $t$ multiplications outputs at most $t+1$ distinct elements; (3) injectivity of the baby steps exactly when $m\le\ord(\alpha)$, with a collision whenever $0<\ord(\alpha)<m$. We compute the exact sensitivity of the optimum: cheapening $(r,m,A)$ by exponents $(\varepsilon_1,\varepsilon_2,\varepsilon_3)$ gives the optimum $\tf15-(\varepsilon_1+2\varepsilon_2+2\varepsilon_3)/5$, so the shadow prices are $(\tf15,\tf25,\tf25)$. We then analyze the untried lever of \emph{adding a floor}. A floor of interior weight $w$ bought at overhead $\delta$ gives the exact optimum $(\gamma+\delta)/(2+\alpha+w)$, which is beneficial iff $\delta(2+\alpha)<\gamma w$; for Harvey this means $\delta<w/5$. In a faithful model where the floor also enters the $M$-leg with weight $\theta$, the cost is at least $\max\{1/(5+4\theta),1/(5+2w)\}$, and reaching $\tf16$ requires $\theta\ge\tf14$ and $w\ge\tf12$ (both attained). No new factoring algorithm is claimed, and $N^{1/5}$ remains an upper bound.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Context}
Deterministic factoring has a short history of exponents. Trial division takes $N^{1/2}$ steps; the Pollard--Strassen method takes $N^{1/4+o(1)}$, as does Lehman's method in its basic form. In 2021 Harvey gave a deterministic algorithm with running time $O(N^{1/5}\log^{16/5}N/(\log\log N)^{3/5})$. It combines a Lehman-style search over pairs of small integers with a baby-step/giant-step computation in $(\mathbb Z/N\mathbb Z)^\times$ that exploits the multiplicative order of a fixed element $\alpha$. After discarding logarithmic factors, the running time is governed by
\begin{equation}\label{eq:cost}
\operatorname{cost}(r,m)=\max\{A,B,C\},\qquad A=\frac{N^{1/2}}{r^{1/2}m},\quad B=r,\quad C=m.
\end{equation}
Here $B$ is the \emph{pair leg}, $C$ is the \emph{baby-step leg} (the powers $\alpha,\dots,\alpha^m$), and $A$ is the \emph{interior}, the matching work that remains. With $r=N^a$ and $m=N^b$, the exponent of \eqref{eq:cost} is
\begin{equation}\label{eq:exp}
E(a,b)=\max\Big\{a,\ b,\ \tf12-\tf a2-b\Big\}.
\end{equation}

\subsection{The question}
Can a cleverer baby-step table, matching procedure, or reorganized interior give a power-of-$N$ improvement? We screened the question with a short linear-programming sensitivity analysis before attacking it by search. The screen closed the question by a theorem. It also pointed to a lever outside the original framing, \emph{adding a floor}, which we show reduces exactly to the interior weight of a new parameter.

\subsection{Summary of results}
\begin{enumerate}
\item $\min E=\tf15$, certified by multipliers $(\tf15,\tf25,\tf25)$ (Theorem~\ref{thm:opt}).
\item Pin 1: $A\cdot C$ is invariant, and $\min_bE(a,b)=\max\{a,(1-a)/4\}$ (Theorems~\ref{thm:prod}--\ref{thm:minb}).
\item Pin 2: output counting; the baby-step chain is optimal (Theorems~\ref{thm:len}--\ref{thm:babyopt}).
\item Pin 3: injectivity iff $m\le\ord(\alpha)$, and this is sharp (Theorems~\ref{thm:inj}--\ref{thm:sharp}).
\item Exact shadow prices $(\tf15,\tf25,\tf25)$; the baby-step leg is closed (Theorem~\ref{thm:sens}, Corollary~\ref{cor:closed}).
\item Add a floor: exact optimum $(\gamma+\delta)/(2+\alpha+w)$; break-even $\delta<w/5$ (Theorems~\ref{thm:floorlower}--\ref{thm:breakeven}).
\item Faithful model: bounds $1/(5+4\theta)$ and $1/(5+2w)$; $\tf16$ iff $\theta\ge\tf14$ and $w\ge\tf12$ (Theorems~\ref{thm:faithful}--\ref{thm:sixth}).
\end{enumerate}

\section{Preliminaries: max-of-affine costs and dual certificates}

\begin{lemma}[Dual certificate]\label{lem:dual}
Let $I$ be finite, $\ell_i\in\mathbb R$, $\lambda_i\ge0$, $\sum_i\lambda_i=1$ and $\sum_i\lambda_i\ell_i=c$. If $T\ge\ell_i$ for all $i$, then $T\ge c$.
\end{lemma}
\begin{proof}
$c=\sum_i\lambda_i\ell_i\le\sum_i\lambda_iT=T$.
\end{proof}

If the $\ell_i$ are affine in a parameter $x$ and $\sum_i\lambda_i\ell_i(x)$ is a constant $c$, then $\max_i\ell_i(x)\ge c$ for every $x$. The certifying multipliers are the \emph{shadow prices} of the legs.

\begin{lemma}[Adding a term is monotone]\label{lem:mono}
If $L\le f(p)$ for all $p$, then $L\le\max\{f(p),F(p)\}$ for all $p$ and every $F$.
\end{lemma}
\begin{proof}
$L\le f(p)\le\max\{f(p),F(p)\}$.
\end{proof}

\section{Harvey's balance}

\begin{theorem}[Optimum $\tf15$]\label{thm:opt}
For all real $a,b$, $E(a,b)\ge\tf15$, with equality at $a=b=\tf15$.
\end{theorem}
\begin{proof}
$\tf15a+\tf25b+\tf25(\tf12-\tf a2-b)=\tf15$; apply Lemma~\ref{lem:dual}. At $a=b=\tf15$ all three legs equal $\tf15$.
\end{proof}

\section{Pin 1: $A\cdot C$ is a single degree of freedom}

\begin{theorem}[Product invariance]\label{thm:prod}
For $m>0$, $A\cdot C=N^{1/2}/r^{1/2}$, independently of $m$.
\end{theorem}
\begin{proof}
Cancel $m$.
\end{proof}

\begin{theorem}[Collapse to the $M$-leg]\label{thm:collapse}
For $N,r,m>0$, $\max\{N^{1/2}/(r^{1/2}m),\,m\}\ge(N/r)^{1/4}$, with equality iff $m=(N/r)^{1/4}$.
\end{theorem}
\begin{proof}
For $x,y\ge0$, $xy\le\max\{x,y\}^2$. By Theorem~\ref{thm:prod}, $A\cdot m=(N/r)^{1/2}=((N/r)^{1/4})^2$. Take square roots. Equality holds iff $A=m$.
\end{proof}

\begin{theorem}[Optimizing out $m$]\label{thm:minb}
For all $a,b$, $\max\{b,\tf12-\tf a2-b\}\ge\tf{1-a}4$, with equality at $b=\tf{1-a}4$. Hence $\min_bE(a,b)=\max\{a,\tf{1-a}4\}$, attained at $b=\tf{1-a}4$.
\end{theorem}
\begin{proof}
The two terms average to $\tf{1-a}4$, and they are equal at $b=\tf{1-a}4$.
\end{proof}

\begin{remark}
The exponent $(1-a)/4$ is that of the $M$-leg $(N/r)^{1/4}$ of Harvey's refined algorithm. The value $\tf15$ has two certificates: $\{M\text{-leg},r\}$ with multipliers $(\tf45,\tf15)$, and $\{\text{interior},r,m\}$ with $(\tf25,\tf15,\tf25)$. Theorem~\ref{thm:minb} shows that the second becomes the first after optimizing out $m$. Re-splitting $m$ only redistributes a product whose split is already AM--GM optimal.
\end{remark}

\section{Pin 2: output counting}

\begin{definition}[Straight-line program]
Let $G$ be a monoid. A program is a list of index pairs $(i_1,j_1),\dots,(i_t,j_t)$. Run from an input $g_0$, it starts with the list $[g_0]$, and instruction $k$ appends $x_{i_k}x_{j_k}$, where an out-of-range index reads as $1$. Each instruction is one multiplication.
\end{definition}

\begin{theorem}\label{thm:len}
A program with $t$ instructions outputs a list of exactly $t+1$ elements.
\end{theorem}
\begin{proof}
Induction on $t$.
\end{proof}

\begin{theorem}[Output counting]\label{thm:count}
If every element of a finite set $S\subseteq G$ occurs in the output of a program with $t$ multiplications, then $|S|\le t+1$.
\end{theorem}
\begin{proof}
$S$ is contained in the set of entries of a list of length $t+1$.
\end{proof}

\begin{theorem}[The baby-step chain is optimal]\label{thm:babyopt}
Let $G$ be a group, $\alpha\in G$ and $1\le m\le\ord(\alpha)$. (i) Any program, from any input, whose output contains $\alpha,\dots,\alpha^m$ uses at least $m-1$ multiplications. (ii) The program whose $j$-th instruction ($0\le j\le m-2$) multiplies entry $j$ by entry $0$ outputs exactly $[\alpha,\alpha^2,\dots,\alpha^m]$ using $m-1$ multiplications.
\end{theorem}
\begin{proof}
(i) The baby steps are distinct by Theorem~\ref{thm:inj}; apply Theorem~\ref{thm:count}. (ii) Induction: the list $[\alpha,\dots,\alpha^{j+1}]$ is extended by $\alpha^{j+1}\cdot\alpha=\alpha^{j+2}$.
\end{proof}

\begin{remark}
In Harvey's algorithm the baby steps are a bare chain of single multiplications, and the companion step performs $m$ gcd computations. Hence $\Theta(m)$ is the information-theoretic floor of this leg in the straight-line model, and it is already met.
\end{remark}

\section{Pin 3: injectivity is a correctness hypothesis}

Harvey's matching step uses the following property: since the baby steps are distinct, thanks to the hypothesis $\ord_N(\alpha)\ge m$, each giant-step value equals at most one of them.

\begin{theorem}[Injectivity]\label{thm:inj}
If $m\le\ord(\alpha)$ (with $\ord(\alpha)=\infty$ allowed), then $\alpha^1,\dots,\alpha^m$ are pairwise distinct.
\end{theorem}
\begin{proof}
If $\alpha^{i+1}=\alpha^{j+1}$ with $0\le i,j<m$, then right cancellation gives $\alpha^i=\alpha^j$. The map $k\mapsto\alpha^k$ is injective on $\{0,\dots,\ord(\alpha)-1\}$, so $i=j$.
\end{proof}

\begin{theorem}[Sharpness]\label{thm:sharp}
If $0<\ord(\alpha)<m$, then $\alpha^1=\alpha^{\ord(\alpha)+1}$ with $\ord(\alpha)+1\le m$, so the baby steps contain a repetition.
\end{theorem}
\begin{proof}
$\alpha^{\ord(\alpha)+1}=\alpha^{\ord(\alpha)}\alpha=\alpha$.
\end{proof}

\begin{example}
Modulo $1001=7\cdot11\cdot13$ the element $10$ has order $6$, since $10^3\equiv-1$. For $m=6$ the baby steps are $10,100,1000,991,901,1$, which are distinct. For $m=7$ the seventh step is $10^7\equiv10$.
\end{example}

\begin{remark}
A weight above $1$ for $m$ in the interior would require a baby step to match several giant-step values. Theorem~\ref{thm:sharp} shows that this is exactly where correctness fails. Weight $1$ is a correctness condition, not slack.
\end{remark}

\section{Exact sensitivity and the closure of the baby-step leg}

Let $E_\varepsilon(a,b)=\max\{a-\varepsilon_1,\ b-\varepsilon_2,\ \tf12-\tf a2-b-\varepsilon_3\}$.

\begin{theorem}[Exact sensitivity]\label{thm:sens}
For all $\varepsilon,a,b$, $E_\varepsilon(a,b)\ge\tf15-\tf{\varepsilon_1+2\varepsilon_2+2\varepsilon_3}5$, and for each $\varepsilon$ equality is attained for some $a,b$.
\end{theorem}
\begin{proof}
Use the multipliers $(\tf15,\tf25,\tf25)$ and Lemma~\ref{lem:dual}. For attainment, let $t$ be the right-hand side and take $a=t+\varepsilon_1$, $b=t+\varepsilon_2$. A direct computation shows the third leg equals $t$.
\end{proof}

\begin{corollary}[The baby-step leg is closed]\label{cor:closed}
If $\varepsilon_2\le0$ (Pin 2) and $\varepsilon_3=0$ (Pin 3), then $E_\varepsilon(a,b)\ge\tf15-\tf{\varepsilon_1}5$ for all $a,b$. Any gain must come through the pair leg, at price $\tf15$.
\end{corollary}
\begin{proof}
Immediate from Theorem~\ref{thm:sens}.
\end{proof}

\begin{remark}
At the optimum all three legs are tight and all multipliers are positive, so every leg binds. A cheapening of any single leg is priced exactly by Theorem~\ref{thm:sens}. For the baby-step leg and the interior this price can never be collected without contradicting Pin 2 or Pin 3.
\end{remark}

\section{Adding a floor}

\begin{definition}
For constants $\gamma,\delta\in\mathbb R$ and $\alpha,w\ge0$, let
$F(a,b,c)=\max\{a,\ b,\ c,\ \gamma+\delta-\alpha a-b-wc\}$.
Harvey's cost corresponds to $\gamma=\alpha=\tf12$, $\delta=0$, with no floor.
\end{definition}

\begin{theorem}[Four-leg weighted AM--GM]\label{thm:floorlower}
For $\alpha,w\ge0$ and all $a,b,c$: $F(a,b,c)\ge(\gamma+\delta)/(2+\alpha+w)$.
\end{theorem}
\begin{proof}
With $T=F(a,b,c)$ we have $a,b,c\le T$, hence $\alpha a\le\alpha T$ and $wc\le wT$, so $\gamma+\delta\le(2+\alpha+w)T$.
\end{proof}

\begin{theorem}[Attainment and uniqueness]\label{thm:floorattain}
At $a=b=c=t:=(\gamma+\delta)/(2+\alpha+w)$ all four legs equal $t$. If $\alpha,w>0$, then $F(a,b,c)\le t$ forces $a=b=c=t$, so the new floor binds after the rebalance.
\end{theorem}
\begin{proof}
$(2+\alpha+w)t=\gamma+\delta\le t+\alpha a+b+wc\le(2+\alpha+w)t$, so all inequalities are equalities. Cancel $\alpha$ and $w$.
\end{proof}

\begin{theorem}[A floor missing the interior is useless]\label{thm:useless}
If $w=0$ and $\delta\ge0$, then $F\ge\gamma/(2+\alpha)$ everywhere.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:floorlower}, $F\ge(\gamma+\delta)/(2+\alpha)\ge\gamma/(2+\alpha)$.
\end{proof}

\begin{theorem}[Break-even law]\label{thm:breakeven}
For $\alpha,w\ge0$: $\dfrac{\gamma+\delta}{2+\alpha+w}<\dfrac{\gamma}{2+\alpha}\iff\delta(2+\alpha)<\gamma w$. For Harvey ($\gamma=\alpha=\tf12$) this reads $\dfrac{1/2+\delta}{5/2+w}<\dfrac15\iff\delta<\dfrac w5$. With $w=\tf12$ and $\delta=0$ the optimum is exactly $\tf16$.
\end{theorem}
\begin{proof}
Cross-multiply by the positive denominators and simplify.
\end{proof}

Thus ``add a floor'' is the weight lever in disguise: its only effect is to add $w$ to the AM--GM denominator. Its break-even overhead $\gamma w/(2+\alpha)$ is $w$ times the old optimum, which for Harvey is $w/5$.

\section{The faithful model}

\begin{definition}
For $\theta,w\ge0$ let
$\Phi_{\theta,w}(a,b,c)=\max\{\tf{1-a}4-\theta c,\ a,\ b,\ c,\ \tf12-\tf a2-b-wc\}$.
\end{definition}

\begin{theorem}[Faithful lower bounds]\label{thm:faithful}
For $\theta,w\ge0$ and all $a,b,c$: $\Phi_{\theta,w}\ge\dfrac1{5+4\theta}$ and $\Phi_{\theta,w}\ge\dfrac1{5+2w}$.
\end{theorem}
\begin{proof}
Let $T=\Phi_{\theta,w}(a,b,c)$. From the $M$-leg, $a\le T$ and $\theta c\le\theta T$ we get $\tf14\le T+\tf T4+\theta T$. From the interior, $a,b\le T$ and $wc\le wT$ we get $\tf12\le T+\tf T2+T+wT$.
\end{proof}

\begin{theorem}[Both couplings are needed]\label{thm:both}
If $\Phi_{\theta,w}(a,b,c)<\tf15$ for some $a,b,c$, then $\theta>0$ and $w>0$.
\end{theorem}
\begin{proof}
If $\theta=0$ or $w=0$, one of the bounds of Theorem~\ref{thm:faithful} equals $\tf15$.
\end{proof}

\begin{theorem}[The $\tf16$ thresholds]\label{thm:sixth}
If $\Phi_{\theta,w}(a,b,c)\le\tf16$, then $\theta\ge\tf14$ and $w\ge\tf12$. Conversely $\Phi_{1/4,1/2}(\tf16,\tf16,\tf16)=\tf16$.
\end{theorem}
\begin{proof}
Invert the bounds of Theorem~\ref{thm:faithful}. For the converse: $\tf{5/6}4-\tf1{24}=\tf16$ and $\tf12-\tf1{12}-\tf16-\tf1{12}=\tf16$.
\end{proof}

\begin{remark}
In all cases we tested with the exact solver of Algorithm~\ref{alg:minimax}, the optimum of $\Phi_{\theta,w}$ equals $\max\{1/(5+4\theta),1/(5+2w)\}$; for example $(\tf18,\tf12)\mapsto\tf2{11}$ and $(\tf12,1)\mapsto\tf17$. In general we have proved only the lower bound, together with attainment at $(\tf14,\tf12)$.
\end{remark}

\section{Algorithms}

\begin{algorithm}[Exact minimax of affine legs]\label{alg:minimax}
Given legs $\ell_i(x)=c_i\cdot x+k_i$ on $\mathbb Q^d$: for each $(d+1)$-subset of legs, solve $c_i\cdot x-t=-k_i$ exactly; discard singular or infeasible solutions; return the least feasible $t$. This is vertex enumeration of the epigraph LP and costs $O(\binom{L}{d+1}d^3)$ operations.
\end{algorithm}

\begin{algorithm}[Baby-step chain]
$x_0\gets\alpha$; for $j=0,\dots,m-2$, set $x_{j+1}\gets x_jx_0$. This uses $m-1$ multiplications, which is optimal.
\end{algorithm}

\begin{algorithm}[Injectivity check]
Compute $\ord(\alpha)$ modulo $N$ by repeated multiplication; the table is collision-free iff $m\le\ord(\alpha)$.
\end{algorithm}

\begin{algorithm}[Floor screen]
Given exponents $(\theta,w,\delta)$ for a candidate parameter, report $\max\{1/(5+4\theta),1/(5+2w)\}$ and the test $\delta<w/5$.
\end{algorithm}

\section{Discussion}
The baby-step leg is a closed variable. Re-splitting $m$ cannot help (Pin 1). Building the table faster cannot help (Pin 2). Making each entry do more work breaks correctness (Pin 3). The exact shadow prices make this quantitative. These results concern an exponent model of one algorithm family. They do not address logarithmic factors or algorithms outside this cost shape, and they do \emph{not} show that $N^{1/5}$ is optimal for deterministic factoring; it remains an upper bound. Methodologically, running the dual screen before a search replaced a long search with a short theorem and redirected attention to a concrete target.

\section{Future directions}
\begin{enumerate}
\item \textbf{Dual-coupled floor existence.} Find an arithmetic parameter $s$ (a second Lehman multiplier or a second order-finding base) that reduces the $M$-leg by $s^{1/4}$ and the interior by $s^{1/2}$ at overhead below $s^{1/10}$; the target is $(\theta,w)\ge(\tf14,\tf12)$.
\item \textbf{Output-counting lower bounds for generic interiors.} Extend Theorem~\ref{thm:count} from one list to two-list collisions, to bound the matching interior below by $\Omega(\#\text{candidates}/\#\text{stored})$.
\item \textbf{Shadow-price monotonicity.} Conjecture that adding legs to a max-of-affine cost weakly raises the shadow price of each original leg that remains binding.
\item \textbf{Injectivity relaxation.} If each value may match up to $k$ baby steps, the interior weight becomes $1-\log k/\log m$; conjecture that this never beats $\tf15$.
\end{enumerate}

