"""Exhaustive census of Pins 2 and 3 over small moduli.

For every modulus 3 <= n <= 300, every unit alpha mod n, and every table length
1 <= m <= ord(alpha) + 3, build the baby-step chain alpha, ..., alpha^m with m-1
multiplications and check:
  (Pin 2) number of distinct outputs <= multiplications + 1;
  (Pin 3) the table is collision-free  <=>  m <= ord(alpha);
  (sharpness) when m > ord(alpha), alpha^1 = alpha^(ord+1)."""
from math import gcd


def order(alpha: int, n: int) -> int:
    x, k = alpha % n, 1
    while x != 1:
        x, k = (x * alpha) % n, k + 1
    return k


def census(nmax: int = 300) -> tuple[int, int]:
    checked = violations = 0
    for n in range(3, nmax + 1):
        for alpha in range(2, n):
            if gcd(alpha, n) != 1:
                continue
            o = order(alpha, n)
            table = [alpha % n]
            for m in range(1, o + 4):
                if m > 1:
                    table.append((table[-1] * alpha) % n)   # one multiplication
                distinct = len(set(table))
                ok = distinct <= (m - 1) + 1
                ok &= (distinct == m) == (m <= o)
                if m > o:
                    ok &= pow(alpha, 1, n) == pow(alpha, o + 1, n)
                checked += 1
                violations += (not ok)
    return checked, violations


if __name__ == "__main__":
    c, v = census()
    print(f"checked {c} (n, alpha, m) triples; violations = {v}")

