from typing import Callable


def slp_run(g0: int, prog: list[tuple[int, int]], mul: Callable[[int, int], int],
            one: int) -> list[int]:
    """Run a straight-line program: instruction (i, j) appends acc[i]*acc[j]."""
    acc = [g0]
    for i, j in prog:
        acc.append(mul(acc[i] if i < len(acc) else one, acc[j] if j < len(acc) else one))
    return acc


def baby_step_chain(alpha: int, m: int, n: int) -> tuple[list[int], int]:
    """alpha, alpha^2, ..., alpha^m mod n using exactly m-1 multiplications."""
    prog = [(j, 0) for j in range(m - 1)]
    out = slp_run(alpha % n, prog, lambda x, y: (x * y) % n, 1)
    return out, len(prog)


def multiplicative_order(alpha: int, n: int) -> int:
    x, k = alpha % n, 1
    while x != 1:
        x, k = (x * alpha) % n, k + 1
    return k


def certify(alpha: int, m: int, n: int) -> dict[str, object]:
    table, mults = baby_step_chain(alpha, m, n)
    o = multiplicative_order(alpha, n)
    distinct = len(set(table))
    return {
        "multiplications": mults,
        "output_counting_ok": distinct <= mults + 1,          # Pin 2
        "lower_bound_met": mults == m - 1,
        "order": o,
        "injective": distinct == m,
        "injective_iff_m_le_order": (distinct == m) == (m <= o),  # Pin 3 (sharp)
    }


if __name__ == "__main__":
    for m in (5, 6, 7):
        print(m, certify(10, m, 1001))

from fractions import Fraction as F


def simple_floor_optimum(w: F, delta: F, gamma: F = F(1, 2), alpha: F = F(1, 2)) -> F:
    """Exact optimum of max{a, b, c, gamma + delta - alpha*a - b - w*c}."""
    return (gamma + delta) / (2 + alpha + w)


def faithful_lower_bound(theta: F, w: F) -> F:
    """Guaranteed lower bound max{1/(5+4 theta), 1/(5+2w)} in the faithful model."""
    return max(1 / (5 + 4 * theta), 1 / (5 + 2 * w))


def floor_screen(theta: F, w: F, delta: F) -> dict[str, object]:
    old = F(1, 5)
    return {
        "simple_optimum": simple_floor_optimum(w, delta),
        "beats_1/5_simple": delta < w / 5,                      # break-even law
        "faithful_lower_bound": faithful_lower_bound(theta, w),
        "can_beat_1/5_faithfully": theta > 0 and w > 0,
        "can_reach_1/6_faithfully": theta >= F(1, 4) and w >= F(1, 2),
        "worth_developing": delta < w / 5 and faithful_lower_bound(theta, w) < old,
    }


if __name__ == "__main__":
    for cand in [(F(0), F(1), F(0)), (F(1, 4), F(1, 2), F(0)), (F(1, 8), F(1, 2), F(1, 20)),
                 (F(1, 4), F(1, 2), F(1, 8))]:
        print(cand, floor_screen(*cand))
